const { execSync } = require('child_process');

function main() {
    const binaryPath = process.argv[2] || '/app/a.out';
    const output = execSync(`objdump -s ${binaryPath}`, { encoding: 'utf8' });

    const result = {};
    let currentAddr = null;

    const lines = output.split('\n');
    for (const line of lines) {
        // Match section content line like: ' 1000 f30f1efa 4883ec08 488b05d9 2f000048  ....H...H.../..H'
        const match = line.match(/^\s+([0-9a-f]+)\s+([0-9a-f\s]{35,45})\s+/);
        if (match) {
            let addr = parseInt(match[1], 16);
            const hexBytes = match[2].trim().split(/\s+/).join('');
            // hexBytes is 16 hex chars (8 bytes) or similar
            for (let i = 0; i < hexBytes.length; i += 8) {
                if (i + 8 <= hexBytes.length) {
                    const chunk = hexBytes.substr(i, 8);
                    // Little endian parsing of 32-bit integer
                    const val = Buffer.from(chunk, 'hex').readUInt32LE(0);
                    result[addr.toString()] = val;
                    addr += 4;
                }
            }
        }
    }
    console.log(JSON.stringify(result));
}

main();
